import torch


class MulY(torch.autograd.Function):
    @staticmethod
    def forward(ctx, x):
        ctx.set_materialize_grads(True)
        return x * 3

    @staticmethod
    def backward(ctx, grad_out):
        return grad_out * 3

@torch.compile(backend="eager", fullgraph=True)
def f(x):
    return MulY.apply(x)

x = torch.tensor(2., requires_grad=True)
expected = MulY.apply(x)
