import torch

class MulY(torch.autograd.Function):
    @staticmethod
    def forward(ctx, x, ys):
        ctx.save_for_backward(ys[0])
        return x * ys[0]

    @staticmethod
    def backward(ctx, grad_out):
        ys, = ctx.saved_tensors 
        return grad_out * ys

@torch.compile(backend="eager", fullgraph=True)
def f(x, ys):
    return MulY.apply(x, ys)

x = torch.tensor(2., requires_grad=True)
ys = [torch.tensor(2.)]
expected = MulY.apply(x, ys)
out = f(x, ys)
assert torch.allclose(out, expected)

